import {loadProductionMaterial} from '../material-production/loader.js';
import {decodeMaterialPack} from '../material-production/pack.js';
import {maps,uvAt,linear,srgb,clamp,normalFromHeight} from './pixels.js';
import {getItem} from './storage.js';
let catalog;
export async function materialCatalog(){if(!catalog)catalog=await(await fetch(new URL('../material-production/catalog.json',import.meta.url),{cache:'no-store'})).json();return catalog;}
async function imagePixels(url,n,flip=true){const blob=await(await fetch(url)).blob(),image=await createImageBitmap(blob,{colorSpaceConversion:'none',premultiplyAlpha:'none'}),canvas=new OffscreenCanvas(n,n),ctx=canvas.getContext('2d',{willReadFrequently:true});if(flip){ctx.translate(0,n);ctx.scale(1,-1);}ctx.drawImage(image,0,0,n,n);image.close();return{width:n,height:n,data:ctx.getImageData(0,0,n,n).data};}
export function tileFromPack(pack,zone,n){const out=maps(n),cols=pack.manifest.atlas.columns,rows=pack.manifest.atlas.rows,g=pack.manifest.atlas.guardFraction||0;zone=Math.max(0,Math.min(cols*rows-1,Number(zone)||0));const base=pack.maps.color[0].width/cols,index=Math.min(pack.maps.color.length-1,Math.max(0,Math.floor(Math.log2(base/n))));for(const id of ['color','normal','surface']){const source=pack.maps[id][index],w=source.width/cols,h=source.height/rows,cx=(zone%cols)*w,cy=Math.floor(zone/cols)*h;for(let y=0;y<n;y++)for(let x=0;x<n;x++){const sx=(g+uvAt(x,n)*(1-g*2))*w-.5,sy=(g+uvAt(y,n)*(1-g*2))*h-.5,ix=Math.floor(sx),iy=Math.floor(sy),tx=sx-ix,ty=sy-iy,i=(y*n+x)*4;const sample=(dx,dy,c)=>source.data[((cy+Math.max(0,Math.min(h-1,iy+dy)))*source.width+cx+Math.max(0,Math.min(w-1,ix+dx)))*4+c];for(let c=0;c<4;c++){let values=[sample(0,0,c),sample(1,0,c),sample(0,1,c),sample(1,1,c)];if(id==='color'&&c<3)values=values.map(v=>linear(v/255));let value=(values[0]*(1-tx)+values[1]*tx)*(1-ty)+(values[2]*(1-tx)+values[3]*tx)*ty;if(id==='color'&&c<3)value=srgb(value)*255;out[id][i+c]=Math.round(clamp(value,0,255));}if(id==='normal'){const nn=[0,1,2].map(c=>out.normal[i+c]/127.5-1),len=Math.hypot(...nn)||1;for(let c=0;c<3;c++)out.normal[i+c]=Math.round((nn[c]/len*.5+.5)*255);}}}return out;}
export async function loadSource(kind,p,n){if(kind==='images'){const out={};for(const [channel,url]of Object.entries(p.images||{})){if(!['color','normal','roughness','metallic','ao','height','mask'].includes(channel)||typeof url!=='string'||!/^data:image\/(png|jpeg|webp);base64,/.test(url)||url.length>18e6)throw Error('Invalid embedded material bitmap');out[channel]=await imagePixels(url,n,!p.recipe);}return out;}
 if(kind==='bitmap'){const images=await loadSource('images',p,n),out=maps(n),height=new Float32Array(n*n);for(let y=0;y<n;y++)for(let x=0;x<n;x++){const src=(Math.min(n-1,Math.floor(uvAt(y,n)*n))*n+Math.min(n-1,Math.floor(uvAt(x,n)*n)))*4,i=(y*n+x)*4;out.color.set(images.color.data.subarray(src,src+4),i);out.normal.set(images.normal?images.normal.data.subarray(src,src+4):[128,128,255,255],i);const h=images.height?(images.height.data[src]/255-.5)*(p.heightScale??.02):0;height[y*n+x]=h;out.surface.set([images.ao?.data[src]??255,images.roughness?.data[src]??180,images.metallic?.data[src]??0,Math.round(clamp(.5+h*40)*255)],i);}if(images.height&&!images.normal)normalFromHeight(out,height);return out;}
 if(kind==='scan'){const bases={rock:'rock_boulder_dry',sand:'sandy_gravel',mud:'mud_cracked_dry_03'},base=bases[p.id];if(!base)throw Error('Unknown scanned material');const [color,normal,surface]=await Promise.all([imagePixels(new URL('../'+base+'_diff.jpg',import.meta.url),n),imagePixels(new URL('../'+base+'_nor_gl.jpg',import.meta.url),n),imagePixels(new URL('../'+base+'_surface.png',import.meta.url),n)]),out=maps(n);for(let y=0;y<n;y++)for(let x=0;x<n;x++){const src=(Math.min(n-1,Math.floor(uvAt(y,n)*n))*n+Math.min(n-1,Math.floor(uvAt(x,n)*n)))*4,i=(y*n+x)*4;out.color.set(color.data.subarray(src,src+4),i);out.normal.set(normal.data.subarray(src,src+4),i);out.surface.set([surface.data[src+1],surface.data[src],0,Math.round(clamp(.5+(surface.data[src+2]/255-.5)*.012*40)*255)],i);}return out;}
 let pack;if(kind==='localPack'){const item=await getItem('assets',p.assetId);if(!item)throw Error('This graph references an imported pack. Import that pack on this device first.');pack=decodeMaterialPack(item.bytes);}else{const cat=await materialCatalog(),entry=cat.entries.find(e=>e.id===p.packId);if(!entry)throw Error('Unknown published material pack');pack=(await loadProductionMaterial(entry)).pack;}return tileFromPack(pack,p.zone||0,n);
}
